'use strict'

module.exports = (...args) => {
  const { data, hash: params } = args.pop()
  const ref = args.length ? args[0] : data.root.page.relativeSrcPath
  if (!ref) return
  const { contentCatalog, page } = data.root
  const context = page.component
    ? Object.assign({ component: page.component.name, version: page.version, module: page.module }, params)
    : params
  const file = contentCatalog.resolvePage(ref, context)
  if (file) return file.pub.url
}
